input.content:
import fs from 'node:fs';
const lines = fs.readFileSync('/tmp/lines1.txt', 'utf8').split('\n').filter(Boolean);
let badHex = 0;
const hexRe = /\\x([0-9A-Fa-f]{2})/g;
for (const L of lines) {
  for (const m of L.matchAll(hexRe)) if (m[1] !== m[1].toLowerCase()) badHex++;
}
let sq = 0, dq = 0, other = 0;
for (const L of lines) {
  if (L.startsWith("b'")) sq++;
  else if (L.startsWith('b"')) dq++;
  else other++;
}
// Cross-check the rule: outer quote is " IFF the payload contains 0x27 and no 0x22.
// Decode each repr back to bytes, then re-derive the expected quote.
function decode(L) {
  const q = L[1];
  const body = L.slice(2, -1);
  const out = [];
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (c === '\\') {
      const n = body[i + 1];
      if (n === 'x') { out.push(parseInt(body.substr(i + 2, 2), 16)); i += 3; }
      else if (n === 't') { out.push(9); i++; }
      else if (n === 'n') { out.push(10); i++; }
      else if (n === 'r') { out.push(13); i++; }
      else if (n === '\\') { out.push(92); i++; }
      else if (n === "'") { out.push(39); i++; }
      else if (n === '"') { out.push(34); i++; }
      else throw new Error('unknown escape \\' + n + ' in ' + L);
    } else out.push(c.charCodeAt(0));
  }
  return { q, bytes: out };
}
let mismatches = 0, len16 = 0;
const seen = new Set();
for (const L of lines) {
  const { q, bytes } = decode(L);
  if (bytes.length === 16) len16++;
  const has39 = bytes.includes(39), has34 = bytes.includes(34);
  const expect = has39 && !has34 ? '"' : "'";
  if (expect !== q) { mismatches++; if (mismatches < 4) console.log('MISMATCH', L); }
  for (const b of bytes) seen.add(b);
}
console.log('lines:', lines.length, 'uppercaseHexEscapes:', badHex);
console.log('outerSingle:', sq, 'outerDouble:', dq, 'other:', other);
console.log('quoteRuleMismatches:', mismatches, 'allLen16:', len16 === lines.length);
console.log('distinct byte values observed:', seen.size, '(of 256)');
const missing = [];
for (let b = 0; b < 256; b++) if (!seen.has(b)) missing.push(b);
console.log('missing byte values:', missing.join(',') || '(none)');

import fs from 'node:fs';
const lines = fs.readFileSync('/tmp/lines1.txt', 'utf8').split('\n').filter(Boolean);
let escSqInSq = 0, escSqInDq = 0, escDqAny = 0, bareSqInDq = 0, bareDqInSq = 0;
for (const L of lines) {
  const q = L[1], body = L.slice(2, -1);
  for (let i = 0; i < body.length; i++) {
    if (body[i] === '\\') {
      const n = body[i + 1];
      if (n === "'") { q === "'" ? escSqInSq++ : escSqInDq++; }
      if (n === '"') escDqAny++;
      i += n === 'x' ? 3 : 1;
      continue;
    }
    if (body[i] === "'" && q === '"') bareSqInDq++;
    if (body[i] === '"' && q === "'") bareDqInSq++;
  }
}
console.log({ escSqInSq, escSqInDq, escDqAny, bareSqInDq, bareDqInSq });

// What does Node do with invalid-UTF-8 argv bytes?
import { Buffer } from 'node:buffer';
const a = process.argv.slice(2);
for (const s of a) {
  console.log(JSON.stringify(s),
    'jsLen=', s.length,
    'codepoints=', [...s].length,
    'utf8Bytes=', Buffer.byteLength(s, 'utf8'),
    'units=', [...s].map(c => c.codePointAt(0).toString(16)).join(' '));
}
